DROP TABLE "d_near_fd" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "d_nulls" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "d_many_columns" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "d_coincidence" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "d_unique_everything" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_composite_ok" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_lookup_codes" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_bcnf_only" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "cc_order_lines" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "cc_orders" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "cc_products" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "cc_customers" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_nokey_inferred" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_cross_copy" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "customers_ref" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_3nf_wide" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_3nf_multi" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_3nf_transitive" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_partial_key3" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_2nf_partial" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_1nf_repeating" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_1nf_delimited" IF EXISTS CASCADE CONSTRAINTS;
DROP TABLE "t_1nf_nokey" IF EXISTS CASCADE CONSTRAINTS;

-- d_tiny: 5 rows where a->b happens to hold -> insufficient_data.
CREATE TABLE "d_tiny" (
  "a" INT, "b" VARCHAR2(8), "c" INT, "d" VARCHAR2(8), "e" INT, "f_note" VARCHAR2(20)
);
-- t_1nf_nokey: no key at all. Rows 61..120 duplicate rows 1..60.
CREATE TABLE "t_1nf_nokey" (
  "rec_id" NUMBER(10),
  "cust_code" NUMBER(10),
  "prod_code" NUMBER(10),
  "qty" NUMBER(10),
  "price" NUMBER(10,2),
  "order_day" NUMBER(10),
  "region" VARCHAR2(8),
  "channel" VARCHAR2(8),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60)
);
-- t_1nf_delimited: tags holds comma-separated lists in ~70% of rows.
CREATE TABLE "t_1nf_delimited" (
  "order_id" NUMBER(10) PRIMARY KEY,
  "customer_id" NUMBER(10),
  "tags" VARCHAR2(60),
  "qty" NUMBER(10),
  "order_date" DATE,
  "status" VARCHAR2(8),
  "ship_city" VARCHAR2(12),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60)
);
-- t_1nf_repeating: phone1, phone2, phone3 repeating group.
CREATE TABLE "t_1nf_repeating" (
  "cust_id" NUMBER(10) PRIMARY KEY,
  "cust_name" VARCHAR2(20),
  "phone1" VARCHAR2(16),
  "phone2" VARCHAR2(16),
  "phone3" VARCHAR2(16),
  "email" VARCHAR2(40),
  "city" VARCHAR2(12),
  "signup_date" DATE,
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- t_2nf_partial: PK (order_id, product_id); product_name/unit_price <- product_id; order_date <- order_id.
CREATE TABLE "t_2nf_partial" (
  "order_id" NUMBER(10),
  "product_id" NUMBER(10),
  "product_name" VARCHAR2(20),
  "unit_price" NUMBER(10,2),
  "qty" NUMBER(10),
  "order_date" DATE,
  "ship_mode" VARCHAR2(8),
  "warehouse" VARCHAR2(8),
  "priority" VARCHAR2(8),
  "note_txt" VARCHAR2(60),
  PRIMARY KEY ("order_id", "product_id")
);
-- t_partial_key3: PK (a,b,c); d depends on (a,b) only.
CREATE TABLE "t_partial_key3" (
  "a" NUMBER(10),
  "b" NUMBER(10),
  "c" NUMBER(10),
  "d" VARCHAR2(16),
  "e" NUMBER(10),
  "f_qty" NUMBER(10),
  "f_status" VARCHAR2(8),
  "f_city" VARCHAR2(12),
  "f_flag" CHAR(1),
  "note_txt" VARCHAR2(60),
  PRIMARY KEY ("a", "b", "c")
);
-- t_3nf_transitive: customer_name/email depend on customer_id.
CREATE TABLE "t_3nf_transitive" (
  "order_id" NUMBER(10) PRIMARY KEY,
  "customer_id" NUMBER(10),
  "customer_name" VARCHAR2(20),
  "customer_email" VARCHAR2(40),
  "order_date" DATE,
  "qty" NUMBER(10),
  "unit_price" NUMBER(10,2),
  "status" VARCHAR2(8),
  "ship_city" VARCHAR2(12),
  "pay_flag" CHAR(1),
  "channel" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- t_3nf_multi: two separate transitive FDs (dept_id, city_id).
CREATE TABLE "t_3nf_multi" (
  "emp_id" NUMBER(10) PRIMARY KEY,
  "emp_name" VARCHAR2(20),
  "dept_id" NUMBER(10),
  "dept_name" VARCHAR2(20),
  "dept_floor" NUMBER(10),
  "city_id" NUMBER(10),
  "city_name" VARCHAR2(20),
  "city_pop" NUMBER(10),
  "hire_date" DATE,
  "salary" NUMBER(10),
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- t_3nf_wide: 1500 rows; supervisor <- (wh_id, aisle, bin).
CREATE TABLE "t_3nf_wide" (
  "loc_id" NUMBER(10) PRIMARY KEY,
  "wh_id" NUMBER(10),
  "aisle" NUMBER(10),
  "bin" NUMBER(10),
  "supervisor" VARCHAR2(20),
  "item_count" NUMBER(10),
  "last_check" DATE,
  "zone" VARCHAR2(8),
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- customers_ref: lookup for t_cross_copy FK.
CREATE TABLE "customers_ref" (
  "customer_id" NUMBER(10) PRIMARY KEY,
  "customer_name" VARCHAR2(20),
  "customer_email" VARCHAR2(40),
  "city" VARCHAR2(12),
  "phone" VARCHAR2(16),
  "signup_date" DATE,
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- t_cross_copy: declared FK; name is a stored copy (4 dirty: 98.4% match).
CREATE TABLE "t_cross_copy" (
  "order_id" NUMBER(10) PRIMARY KEY,
  "customer_id" NUMBER(10),
  "customer_name" VARCHAR2(20),
  "order_date" DATE,
  "qty" NUMBER(10),
  "unit_price" NUMBER(10,2),
  "status" VARCHAR2(8),
  "ship_city" VARCHAR2(12),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60),
  CONSTRAINT fk_cross_customer FOREIGN KEY ("customer_id")
    REFERENCES "customers_ref" ("customer_id")
);
-- t_nokey_inferred: no declared key; badge_no unique in data.
CREATE TABLE "t_nokey_inferred" (
  "badge_no" NUMBER(10),
  "emp_name" VARCHAR2(20),
  "dept_id" NUMBER(10),
  "dept_name" VARCHAR2(20),
  "hire_date" DATE,
  "salary" NUMBER(10),
  "city" VARCHAR2(12),
  "status" VARCHAR2(8),
  "lvl" NUMBER(10),
  "note_txt" VARCHAR2(60)
);
-- cc_customers: normalized reference.
CREATE TABLE "cc_customers" (
  "customer_id" NUMBER(10) PRIMARY KEY,
  "customer_name" VARCHAR2(20),
  "customer_email" VARCHAR2(40),
  "city" VARCHAR2(12),
  "phone" VARCHAR2(16),
  "signup_date" DATE,
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- cc_products: normalized reference.
CREATE TABLE "cc_products" (
  "product_id" NUMBER(10) PRIMARY KEY,
  "product_name" VARCHAR2(20),
  "category" VARCHAR2(8),
  "unit_price" NUMBER(10,2),
  "weight" NUMBER(10),
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- cc_orders: normalized; FK to cc_customers.
CREATE TABLE "cc_orders" (
  "order_id" NUMBER(10) PRIMARY KEY,
  "customer_id" NUMBER(10),
  "order_date" DATE,
  "status" VARCHAR2(8),
  "ship_city" VARCHAR2(12),
  "total_amt" NUMBER(10,2),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60),
  CONSTRAINT fk_cco_customer FOREIGN KEY ("customer_id")
    REFERENCES "cc_customers" ("customer_id")
);
-- cc_order_lines: normalized; composite key, full-key deps only.
CREATE TABLE "cc_order_lines" (
  "order_id" NUMBER(10),
  "product_id" NUMBER(10),
  "qty" NUMBER(10),
  "price_charged" NUMBER(10,2),
  "discount" NUMBER(10),
  "ship_mode" VARCHAR2(8),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60),
  PRIMARY KEY ("order_id", "product_id"),
  CONSTRAINT fk_ccol_order FOREIGN KEY ("order_id") REFERENCES "cc_orders" ("order_id"),
  CONSTRAINT fk_ccol_product FOREIGN KEY ("product_id") REFERENCES "cc_products" ("product_id")
);
-- t_bcnf_only: teacher->subject (2 teachers/subject); 3NF but not BCNF.
CREATE TABLE "t_bcnf_only" (
  "student_id" NUMBER(10),
  "subject_code" NUMBER(10),
  "teacher_name" VARCHAR2(12),
  "grade" CHAR(1),
  "semester" VARCHAR2(8),
  "note_txt" VARCHAR2(60),
  PRIMARY KEY ("student_id", "subject_code")
);
-- t_lookup_codes: code is the key.
CREATE TABLE "t_lookup_codes" (
  "code" VARCHAR2(8) PRIMARY KEY,
  "description" VARCHAR2(40),
  "category" VARCHAR2(8),
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- t_composite_ok: PK (a,b); c,d depend on the whole key.
CREATE TABLE "t_composite_ok" (
  "a" NUMBER(10),
  "b" NUMBER(10),
  "c" VARCHAR2(16),
  "d" VARCHAR2(16),
  "e" NUMBER(10),
  "f_status" VARCHAR2(8),
  "note_txt" VARCHAR2(60),
  PRIMARY KEY ("a", "b")
);
-- d_unique_everything: every value unique.
CREATE TABLE "d_unique_everything" (
  "id" NUMBER(10) PRIMARY KEY,
  "u1" NUMBER(10),
  "u2" NUMBER(10),
  "code" VARCHAR2(12),
  "email" VARCHAR2(40),
  "token" CHAR(32),
  "note_txt" VARCHAR2(20),
  "flag" CHAR(1)
);
-- d_coincidence: independent categoricals (seeded RNG literals).
CREATE TABLE "d_coincidence" (
  "id" NUMBER(10) PRIMARY KEY,
  "cat_a" VARCHAR2(8),
  "cat_b" VARCHAR2(8),
  "cat_c" VARCHAR2(8),
  "cat_d" VARCHAR2(8),
  "cat_e" VARCHAR2(8),
  "cat_f" VARCHAR2(8),
  "cat_g" VARCHAR2(8),
  "qty" NUMBER(10),
  "note_txt" VARCHAR2(60)
);
-- d_many_columns: 15 independent categoricals x 1000 rows (seeded RNG).
CREATE TABLE "d_many_columns" (
  "id" NUMBER(10) PRIMARY KEY,
  "c01" VARCHAR2(8),
  "c02" VARCHAR2(8),
  "c03" VARCHAR2(8),
  "c04" VARCHAR2(8),
  "c05" VARCHAR2(8),
  "c06" VARCHAR2(8),
  "c07" VARCHAR2(8),
  "c08" VARCHAR2(8),
  "c09" VARCHAR2(8),
  "c10" VARCHAR2(8),
  "c11" VARCHAR2(8),
  "c12" VARCHAR2(8),
  "c13" VARCHAR2(8),
  "c14" VARCHAR2(8)
);
-- d_nulls: heavy NULLs, independent columns.
CREATE TABLE "d_nulls" (
  "id" NUMBER(10) PRIMARY KEY,
  "c1" VARCHAR2(12),
  "c2" VARCHAR2(12),
  "c3" VARCHAR2(12),
  "n1" NUMBER(10),
  "note_txt" VARCHAR2(60),
  "flag" CHAR(1),
  "qty" NUMBER(10)
);
-- d_near_fd: dept_id->dept_name with 2 dirty rows (1%).
CREATE TABLE "d_near_fd" (
  "id" NUMBER(10) PRIMARY KEY,
  "dept_id" NUMBER(10),
  "dept_name" VARCHAR2(20),
  "hire_date" DATE,
  "salary" NUMBER(10),
  "city" VARCHAR2(12),
  "status" VARCHAR2(8),
  "note_txt" VARCHAR2(60)
);
-- d_dirty_pairs: every group has 2 disagreeing rows.
CREATE TABLE "d_dirty_pairs" (
  "id" NUMBER(10) PRIMARY KEY,
  "pair_id" NUMBER(10),
  "side" VARCHAR2(8),
  "note_txt" VARCHAR2(60),
  "flag" CHAR(1),
  "amt" NUMBER(10)
);
-- d_equiv_cols: 10-row lookup; code <-> country 1-1.
CREATE TABLE "d_equiv_cols" (
  "code" VARCHAR2(8) PRIMARY KEY,
  "country" VARCHAR2(20),
  "capital" VARCHAR2(20),
  "currency" VARCHAR2(12),
  "note_txt" VARCHAR2(60)
);
-- d_wide_text: LOB/JSON excluded from FD search.
CREATE TABLE "d_wide_text" (
  "id" NUMBER(10) PRIMARY KEY,
  "title" VARCHAR2(120),
  "body" CLOB,
  "attachment" BLOB,
  "meta" CLOB,
  "created_date" DATE,
  "author" VARCHAR2(20)
);
-- d_name_trap: naming suggests user_id->user_name; data disagrees.
CREATE TABLE "d_name_trap" (
  "id" NUMBER(10) PRIMARY KEY,
  "user_id" NUMBER(10),
  "user_name" VARCHAR2(20),
  "signup_date" DATE,
  "status" VARCHAR2(8),
  "city" VARCHAR2(12),
  "logins" NUMBER(10),
  "note_txt" VARCHAR2(60)
);
-- t_big_sample: 55000 rows (> MAX_ROWS_PER_TABLE); transitive FD.
CREATE TABLE "t_big_sample" (
  "id" NUMBER(10) PRIMARY KEY,
  "customer_id" NUMBER(10),
  "customer_name" VARCHAR2(20),
  "order_date" DATE,
  "qty" NUMBER(10),
  "unit_price" NUMBER(10,2),
  "status" VARCHAR2(8),
  "ship_city" VARCHAR2(12),
  "flag" CHAR(1),
  "note_txt" VARCHAR2(60)
);

